#!/usr/bin/env node
/**
 * Builds React icon components from the DBIM Toolkit SVGs.
 *
 *   Source:  src/assets/icons/dbim/<name>.svg   (downloaded unchanged from
 *            https://dbimtoolkit.digifootprint.gov.in/visual-library?slug=iconography)
 *   Output:  src/components/ui/Icon/dbim/icons.generated.tsx   (do not edit by hand)
 *
 * Run after adding or replacing an SVG:  npm run icons
 *
 * Each SVG is optimised with SVGO, its ids are prefixed (so several icons on one page never
 * share a clip-path id) and the DBIM grey (#2D2D2D) becomes `currentColor`, so the Icon
 * component's `tone` decides the colour.
 */
import { readFileSync, readdirSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { optimize } from 'svgo';

const SOURCE_DIR = 'src/assets/icons/dbim';
const OUTPUT = 'src/components/ui/Icon/dbim/icons.generated.tsx';
const DBIM_INK = /#2d2d2d|#2b2b2b/gi;

/**
 * Per-icon adjustments so the result matches the Figma:
 *   dropFirstPath — the toolkit's X has a square frame; the Figma footer uses the bare glyph.
 *   rotate        — degrees; extra icons derived from another SVG (chevron down = right ↻ 90°).
 */
const ADJUST = { x: { dropFirstPath: true } };
const DERIVED = [{ name: 'chevron-down', from: 'chevron-right', rotate: 90 }];

const pascal = (name) =>
  'Dbim' +
  name
    .split('-')
    .map((part) => part[0].toUpperCase() + part.slice(1))
    .join('');

function convert(name, svg, { dropFirstPath = false, rotate = 0 } = {}) {
  const { data } = optimize(svg, {
    multipass: true,
    plugins: [
      'preset-default',
      'removeDimensions',
      { name: 'prefixIds', params: { prefix: `dbim-${name}`, delim: '-' } },
    ],
  });
  const viewBox = /viewBox="([^"]+)"/.exec(data)?.[1];
  if (!viewBox) throw new Error(`${name}: no viewBox`);
  // Keep paint set on the root <svg> (e.g. fill="none" for stroke icons) on a wrapping group.
  const root = /^<svg[^>]*>/.exec(data)[0];
  const paint = [
    ...root.matchAll(/\s(fill|stroke|stroke-width|stroke-linecap|stroke-linejoin)="[^"]*"/g),
  ]
    .map((match) => match[0])
    .join('');
  let body = data.replace(/^<svg[^>]*>/, '').replace(/<\/svg>\s*$/, '');
  if (paint) body = `<g${paint}>${body}</g>`;
  if (dropFirstPath) body = body.replace(/<path[^>]*\/>/, '');
  body = body.replace(DBIM_INK, 'currentColor');
  if (rotate) {
    const [x, y, w, h] = viewBox.split(/\s+/).map(Number);
    body = `<g transform="rotate(${rotate} ${x + w / 2} ${y + h / 2})">${body}</g>`;
  }
  return { viewBox, body };
}

const sources = Object.fromEntries(
  readdirSync(SOURCE_DIR)
    .filter((file) => file.endsWith('.svg'))
    .sort()
    .map((file) => [
      path.basename(file, '.svg'),
      readFileSync(path.join(SOURCE_DIR, file), 'utf8'),
    ]),
);

const icons = [
  ...Object.entries(sources).map(([name, svg]) => [name, convert(name, svg, ADJUST[name])]),
  ...DERIVED.map(({ name, from, rotate }) => [name, convert(name, sources[from], { rotate })]),
].sort(([a], [b]) => a.localeCompare(b));

const lines = icons.map(
  ([name, { viewBox, body }]) =>
    `export const ${pascal(name)} = createDbimIcon('${pascal(name)}', '${viewBox}', ${JSON.stringify(body)});`,
);

writeFileSync(
  OUTPUT,
  `/* Generated by scripts/build-dbim-icons.mjs from src/assets/icons/dbim — do not edit. */\nimport { createDbimIcon } from './createDbimIcon';\n\n${lines.join('\n')}\n`,
);
console.log(`✓ ${icons.length} DBIM icons → ${OUTPUT}`);
